import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String p = br.readLine().trim();

        for (int len = 1; len <= n / 2; len++) {
            if (n % len != 0) continue;
            if (isPolygram(p, len)) {
                System.out.println(p.substring(0, len));
                return;
            }
        }
        System.out.println("*");
    }

    private static boolean isPolygram(String s, int len) {
        int n = s.length();
        int[] base = new int[26];
        for (int i = 0; i < len; i++) {
            base[s.charAt(i) - 'a']++;
        }

        int[] cur = new int[26];
        for (int start = len; start < n; start += len) {
            Arrays.fill(cur, 0);
            for (int i = start; i < start + len; i++) {
                cur[s.charAt(i) - 'a']++;
            }
            for (int c = 0; c < 26; c++) {
                if (cur[c] != base[c]) {
                    return false;
                }
            }
        }
        return true;
    }
}
